// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: caller (an address that will be a contract) and the desired new owner
    function testFuzz_property(address attackerAddr, address newOwner) public {
        // Keep attackerAddr non-zero and distinct from the current owner to create an interesting scenario
        vm.assume(attackerAddr != address(0));
        vm.assume(newOwner != address(0));
        address originalOwner = c.owner();

        // Deploy an attacker contract at a deterministic address using create2-like trick is unnecessary; instead deploy normally.
        // We need a contract caller so that msg.sender != tx.origin when it calls c.setOwner.
        Attacker attacker = new Attacker(c);

        // Fund the attacker so it can make calls if needed
        vm.deal(address(attacker), 1 ether);

        // The attacker's call: it will call c.setOwner(newOwner) from a contract (so msg.sender in c is attacker contract)
        bool ok;
        try attacker.doCall(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: After any call to setOwner, either the caller was the current owner and owner() equals newOwner,
        // or the caller was not the current owner and owner() remains originalOwner. The reference implementation enforces
        // that only the current owner can change owner, so a contract caller (not equal to originalOwner) must NOT change owner.
        // We assert that if the caller was not the original owner (the attacker contract), then owner() != newOwner.
        // This will hold for the reference contract for all inputs, but the mutant (which checks msg.sender == tx.origin)
        // allows the contract attacker to succeed, so the assertion will fail for some inputs (and the fuzzer will find them).

        // The single required assertion reading c's public surface:
        if (address(attacker) != originalOwner) {
            // If attacker contract is not the original owner, reference C must not have changed owner to newOwner.
            assertTrue(c.owner() != newOwner);
        } else {
            // If by chance the attacker contract equals the original owner (extremely unlikely but admissible), then
            // owner should be either unchanged or updated to newOwner by a legitimate owner call; both are acceptable,
            // so assert that owner is either originalOwner or newOwner (this is still an observation of c.owner()).
            address cur = c.owner();
            assertTrue(cur == originalOwner || cur == newOwner);
        }
    }
}

// Minimal adversarial helper: a contract that calls C.setOwner from a contract context
contract Attacker {
    C public target;
    constructor(C _t) {
        target = _t;
    }
    function doCall(address _newOwner) external {
        // call setOwner from this contract (so msg.sender in C will be this contract)
        target.setOwner(_newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameters: an address 'attackerEOA' that will be the tx.origin and an address 'newOwner'
    // The adversarial helper is a contract which will call c.setOwner(newOwner) from its context (msg.sender = helper)
    // The correct contract requires msg.sender == owner, so a contract caller (helper) should NOT be able to change owner
    // because the helper is not the owner. The mutant comparing msg.sender == tx.origin allows the helper to succeed
    // when tx.origin is the original owner EOA.
    function testFuzz_property(address attackerEOA, address newOwner) public {
        // Keep domain wide but avoid the zero address for newOwner to ensure meaningful change
        // (zero address is allowed in principle, but filtering it widens chance to observe change)
        vm.assume(attackerEOA != address(0));
        vm.assume(newOwner != address(0));
        // Ensure attackerEOA is not the deployed contract's address
        vm.assume(attackerEOA != address(this));
        vm.assume(attackerEOA != address(c));

        // The initial owner is the test contract (setUp deployed c via new C()), so owner() == address(this)
        address initialOwner = c.owner();
        // sanity: should be this
        assertTrue(initialOwner == address(this));

        // Deploy helper contract which will call c.setOwner(newOwner) from its own msg.sender
        CallerHelper helper = new CallerHelper(c);

        // Fund attackerEOA so it can be tx.origin (EOA) when we prank
        vm.deal(attackerEOA, 1 ether);

        // Now simulate attackerEOA initiating a call that causes the helper contract to call c.setOwner(newOwner)
        // We make attackerEOA the tx.origin by vm.prank(attackerEOA) and then call helper.callSetOwner(newOwner)
        // From c's perspective: msg.sender == address(helper), tx.origin == attackerEOA
        vm.prank(attackerEOA);
        helper.callSetOwner(newOwner);

        // Exactly one assertion: in the correct contract, a contract caller (helper) that is NOT the current owner
        // cannot change owner; therefore owner() must still equal initialOwner. The mutant (msg.sender == tx.origin)
        // would allow the change when tx.origin == initialOwner (attackerEOA == initialOwner), which the fuzzer can pick.
        assertTrue(c.owner() == initialOwner);
    }
}

// Minimal adversarial helper: simply calls setOwner on target contract
contract CallerHelper {
    C target;
    constructor(C _target) { target = _target; }
    function callSetOwner(address _newOwner) external {
        // call setOwner from this contract's context
        target.setOwner(_newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: an address that will act as the EOA attacker and an address newOwner to pass to setOwner
    function testFuzz_property(address attacker, address newOwner) public {
        // keep addresses non-zero and distinct to avoid degenerate cases
        vm.assume(attacker != address(0));
        vm.assume(newOwner != address(0));
        // ensure attacker is not the initial owner (deployer from setUp)
        address initialOwner = c.owner();
        vm.assume(attacker != initialOwner);

        // Deploy a helper contract that will call c.setOwner on behalf of attacker.
        // The helper will perform an external call into c; its msg.sender will be the helper contract,
        // and tx.origin will be the attacker EOA when we use vm.prank(attacker).
        Caller helper = new Caller(c);

        // The reference contract requires msg.sender == owner. Since helper (a contract) will be msg.sender,
        // and helper != initialOwner, the reference MUST revert / not allow the change when the call is made by helper.
        // We will have the attacker EOA initiate the call through the helper (so tx.origin == attacker).

        // make sure attacker has some ETH so tx.origin is an EOA performing an external call (not strictly required here)
        vm.deal(attacker, 1 ether);

        bool ok;
        // have attacker EOA instruct the helper to call setOwner(newOwner) (so tx.origin==attacker, msg.sender==helper)
        vm.prank(attacker);
        try helper.doCallSetOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property (single assertion): For all admissible inputs (attacker != initial owner),
        // the genuine reference contract C will only accept setOwner when msg.sender == owner. Because here msg.sender==helper (a contract != owner),
        // the reference must reject, so ok must be false. The mutant that compares msg.sender to tx.origin will accept when tx.origin==attacker
        // even though msg.sender!=owner, making ok true for some inputs; thus this assertion distinguishes them.
        assertTrue(!ok);

        // As required, we only assert by observing c via its public behavior (the success boolean of the call)
    }
}

// Minimal helper that forwards the call into C
contract Caller {
    C public c;
    constructor(C _c) {
        c = _c;
    }
    function doCallSetOwner(address _owner) external {
        // forward a plain external call; if target reverts, this will revert
        c.setOwner(_owner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: caller (which will be a contract attacker) and newOwner (the target owner to set)
    function testFuzz_property(address callerEOA, address newOwner) public {
        // Keep domain wide but avoid zero addresses for clarity
        vm.assume(callerEOA != address(0));
        vm.assume(newOwner != address(0));
        // Deploy an attacking contract that will call c.setOwner(newOwner)
        Attacker attacker = new Attacker(c, newOwner, callerEOA);

        // Fund the EOA that will be tx.origin so the call can be made
        vm.deal(callerEOA, 1 ether);

        // Ensure current owner is the deployer (setUp), who should be able to change owner but attacker should not be able to
        address originalOwner = c.owner();

        // The adversarial scenario: an EOA (callerEOA) calls the attacker contract, which in turn calls c.setOwner(newOwner)
        // For the correct contract C: only originalOwner may change owner; the attacker's call should fail to change owner.
        // For the mutant: since require compares msg.sender == tx.origin, the attacker's call may succeed when tx.origin == callerEOA.

        // Have callerEOA invoke the attacker (so tx.origin == callerEOA, msg.sender inside C will be the attacker contract address)
        vm.prank(callerEOA);
        attacker.attack();

        // The universal invariant we assert: after this interaction, owner is either unchanged (attack failed)
        // or changed only if the tx.origin itself was the original owner (i.e., the EOA that initiated call was the actual owner).
        // The correct contract enforces: owner == originalOwner (attack cannot succeed when initiated by non-owner EOAs)
        // So we assert that owner == originalOwner OR tx.origin-witness case: owner == newOwner only if callerEOA == originalOwner.
        // We cannot read tx.origin here, but we can express the condition using the fuzzed callerEOA variable.

        // Exactly one assertTrue reading c.owner(): the correct contract will always satisfy owner == originalOwner || callerEOA == originalOwner
        // The mutant can violate this by setting owner == newOwner while callerEOA != originalOwner.
        assertTrue(c.owner() == originalOwner || callerEOA == originalOwner);
    }
}

// Minimal adversarial helper: upon being called by an EOA, it calls into C to set the owner to a predetermined address.
contract Attacker {
    C immutable target;
    address immutable newOwner;
    address immutable expectedOrigin;
    constructor(C _target, address _newOwner, address _expectedOrigin) {
        target = _target;
        newOwner = _newOwner;
        expectedOrigin = _expectedOrigin;
    }
    // Called by an EOA (tx.origin == callerEOA). This contract forwards the call to target.setOwner
    function attack() external {
        // Forward call to target; msg.sender in target will be this contract's address, tx.origin will be the EOA
        target.setOwner(newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: callerContract (address to deploy as a contract caller) and newOwner (address to set)
    function testFuzz_property(address callerContractSeed, address newOwner) public {
        // Keep addresses wide but avoid zero address for deploy target which could be problematic
        vm.assume(callerContractSeed != address(0));

        // Deploy a minimal caller contract at an address derived from the seed by creating it with CREATE
        // We cannot deploy at an arbitrary address deterministically from an address seed, so instead
        // use the seed's solidity address as the "owner" EOA that will originate txs, and deploy a small
        // forwarder contract using that EOA as deployer to ensure the forwarder is a contract and msg.sender != tx.origin

        // Ensure the seed is an EOA we control by giving it some ETH and using vm.prank to deploy
        vm.deal(callerContractSeed, 1 ether);
        vm.startPrank(callerContractSeed);
        CallerContract forwarder = new CallerContract();
        vm.stopPrank();

        // At this point forwarder is a contract (msg.sender != tx.origin when it calls c), and callerContractSeed is the tx.origin
        // The general rule: only the current owner (c.owner()) may successfully call setOwner. We check calls originate from the contract.

        // Record current owner
        address before = c.owner();

        // Have the forwarder contract attempt to call c.setOwner(newOwner)
        // The call will succeed on the reference iff msg.sender (the forwarder contract) equals the current owner.
        // For the reference contract, only the current on-chain owner (an address stored in c.owner()) can make the call succeed.
        bool ok;
        try forwarder.callSetOwner(address(c), newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert the universal property: the call succeeded iff the contract caller (forwarder) is equal to the stored owner.
        // We observe c only via its public getter.
        assertTrue(ok == (address(forwarder) == before));
    }
}

// Minimal helper contract that calls C.setOwner; it ensures msg.sender != tx.origin when used from an EOA deployer
contract CallerContract {
    function callSetOwner(address target, address newOwner) external {
        C(target).setOwner(newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameter: a candidate new owner address
    function testFuzz_property(address newOwner) public {
        // keep domain wide but avoid the zero address to be a meaningful owner value
        // zero-address is allowed by contract, but to ensure change we prefer non-zero
        // still allow zero to keep wide domain
        vm.prank(address(c)); // ensure we are not accidentally the owner yet

        // The deployer (this contract) is not the owner; the owner is the test runner (address(this) in setUp)
        // In setUp() we deployed c via this contract, so this contract is owner already.
        // To be explicit, ensure msg.sender is this contract when calling setOwner
        // The call must be from the owner to succeed; use prank to set msg.sender correctly.

        // Call setOwner as the current owner (this contract)
        vm.startPrank(address(this));
        bool ok;
        // catch revert vs success as admissible behavior; both implementations should not revert when caller is owner
        try c.setOwner(newOwner) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The reference contract: for any newOwner and when called by owner, setOwner returns true and updates owner.
        // So after a successful (non-reverting) invocation, the public owner getter must equal newOwner and the return must be true.
        // We express a single universal assertion that must hold for the reference and which the mutant violates for some input:
        // If the call completed successfully (ok == true) then c.owner() == newOwner.
        // This assertion reads c through its public getter only.
        assertTrue(!ok || c.owner() == newOwner);
    }
}
